import React from "react";
import './keyboard.css';

interface KeyboardProps{
    onKeyClick: (key: string) => void;
}

const Keyboard: React.FC<KeyboardProps> = ({ onKeyClick }) => {
    const rowonekeys = ['Q','W','E','R','T','Y','U','I','O','P'];
    const handleMouseClick = (letter: string) => {
        onKeyClick(letter);
    };

    return(
        <>
            <div className="keyboardcontainer">
                <div className="linecontainer">
                    {rowonekeys.map((key) => (
                        <div>{key}</div>
                        )
                    )}
                </div>
                <div className="linecontainer">
                    <div>A</div>
                    <div>S</div>
                    <div>D</div>
                    <div>F</div>
                    <div>G</div>
                    <div>H</div>
                    <div>J</div>
                    <div>K</div>
                    <div>L</div>
                </div>
                <div className="linecontainer">
                    <div>ENTER</div>
                    <div>Z</div>
                    <div>X</div>
                    <div>C</div>
                    <div>V</div>
                    <div>B</div>
                    <div>N</div>
                    <div>M</div>
                    <div>BACK</div>
                </div>
            </div>
        </>
    );
}

export default Keyboard;
